create table app.contact(id uuid primary key default gen_random_uuid(),org_id uuid not null references app.organization(id)on delete cascade,name text not null check(length(name)between 1 and 120),phone_e164 text check(phone_e164~'^\+[1-9][0-9]{1,14}$'),preferred_language text not null default 'ms' check(preferred_language in('ms','en','zh')),do_not_contact boolean not null default false,deletion_pending boolean not null default false,revision int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,id));
create table app.contact_note(id uuid primary key default gen_random_uuid(),org_id uuid not null references app.organization(id)on delete cascade,contact_id uuid not null,text text not null check(length(text)between 1 and 5000),actor_id uuid not null,created_at timestamptz not null default now(),unique(org_id,id),foreign key(org_id,contact_id)references app.contact(org_id,id)on delete cascade);
create table app.consent_record(id uuid primary key default gen_random_uuid(),org_id uuid not null references app.organization(id)on delete cascade,contact_id uuid not null,channel text not null check(channel in('phone','whatsapp')),purpose text not null check(purpose in('service','marketing')),granted boolean not null,source text not null,evidence text not null,actor_id uuid not null,created_at timestamptz not null default now(),recorded_at timestamptz not null default now(),unique(org_id,id),foreign key(org_id,contact_id)references app.contact(org_id,id)on delete cascade);
grant select,insert on app.contact,app.contact_note,app.consent_record to jomcall_app;
grant update(name,phone_e164,preferred_language,do_not_contact,revision,updated_at)on app.contact to jomcall_app;
do $$declare t text;begin foreach t in array array['contact','contact_note','consent_record']loop
 execute format('alter table app.%I enable row level security',t);execute format('alter table app.%I force row level security',t);
 execute format('create policy tenant_read on app.%I for select to jomcall_app using(org_id=nullif(current_setting(''app.org_id'',true),'''')::uuid and app_private.active_role(org_id)is not null)',t);
 if t<>'contact'then execute format('create policy actor_insert on app.%I for insert to jomcall_app with check(org_id=nullif(current_setting(''app.org_id'',true),'''')::uuid and actor_id=nullif(current_setting(''app.user_id'',true),'''')::uuid and app_private.active_role(org_id)is not null and exists(select 1 from app.contact c where c.org_id=org_id and c.id=contact_id and not c.deletion_pending))',t);end if;
 end loop;end $$;
create policy contact_insert on app.contact for insert to jomcall_app with check(org_id=nullif(current_setting('app.org_id',true),'')::uuid and app_private.active_role(org_id)is not null and not deletion_pending);
create policy contact_update on app.contact for update to jomcall_app using(org_id=nullif(current_setting('app.org_id',true),'')::uuid and app_private.active_role(org_id)is not null and not deletion_pending)with check(org_id=nullif(current_setting('app.org_id',true),'')::uuid and app_private.active_role(org_id)is not null and not deletion_pending);
create index contact_timeline on app.contact(org_id,created_at desc,id desc);
create index contact_phone on app.contact(org_id,phone_e164)where phone_e164 is not null;
create index note_timeline on app.contact_note(org_id,contact_id,created_at desc,id desc);
create index consent_timeline on app.consent_record(org_id,contact_id,created_at desc,id desc);
